SELECT *
FROM t_stock_flow
WHERE biz_type = #{bizType}
  AND biz_id = #{bizId}
ORDER BY flow_id ASC

SELECT flow_id, flow_no, product_id, sku_id, warehouse_id, batch_id, flow_type, biz_type, biz_id, direction, quantity, weight, unit_price, amount, before_quantity, after_quantity, before_avg_cost, after_avg_cost, operate_by, operate_time, create_time, update_time FROM t_stock_flow
AND product_id = #{queryForm.productId}
AND sku_id = #{queryForm.skuId}
AND flow_type = #{queryForm.flowType}
AND biz_type = #{queryForm.bizType}
AND direction = #{queryForm.direction}
ORDER BY operate_time DESC, flow_id DESC
